CREATE TABLE public.user_roles (user_id uuid NOT NULL, role text NOT NULL CHECK (role IN ('moderator','admin')), PRIMARY KEY(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_community_moderator() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('moderator','admin')) $$;
REVOKE ALL ON FUNCTION public.is_community_moderator() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_community_moderator() TO authenticated;
CREATE TABLE public.community_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL DEFAULT auth.uid(), target_kind text NOT NULL CHECK(target_kind IN ('post','comment','poll')), target_id uuid NOT NULL, reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 1000), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','dismissed','removed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(reporter_id,target_kind,target_id));
GRANT SELECT,INSERT ON public.community_reports TO authenticated; GRANT ALL ON public.community_reports TO service_role;
ALTER TABLE public.community_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "report own flags" ON public.community_reports FOR INSERT TO authenticated WITH CHECK(reporter_id=auth.uid() AND status='pending');
CREATE POLICY "read own or moderation reports" ON public.community_reports FOR SELECT TO authenticated USING(reporter_id=auth.uid() OR public.is_community_moderator());
CREATE TABLE public.community_hidden(target_kind text NOT NULL CHECK(target_kind IN ('post','comment','poll')), target_id uuid NOT NULL, moderator_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(target_kind,target_id));
GRANT SELECT ON public.community_hidden TO anon,authenticated; GRANT ALL ON public.community_hidden TO service_role;
ALTER TABLE public.community_hidden ENABLE ROW LEVEL SECURITY;
CREATE POLICY "hidden identifiers public" ON public.community_hidden FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.community_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('reply','vote')), target_id uuid NOT NULL, message text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.community_notifications TO authenticated; GRANT UPDATE(read_at) ON public.community_notifications TO authenticated; GRANT ALL ON public.community_notifications TO service_role;
ALTER TABLE public.community_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own notifications" ON public.community_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "mark own notification read" ON public.community_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.resolve_community_report(report_id uuid, decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.community_reports; BEGIN IF NOT public.is_community_moderator() THEN RAISE EXCEPTION 'Moderator access required'; END IF; IF decision NOT IN ('dismissed','removed') THEN RAISE EXCEPTION 'Invalid decision'; END IF; SELECT * INTO r FROM public.community_reports WHERE id=report_id AND status='pending' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Report already resolved'; END IF; IF decision='removed' THEN INSERT INTO public.community_hidden(target_kind,target_id,moderator_id) VALUES(r.target_kind,r.target_id,auth.uid()) ON CONFLICT DO NOTHING; END IF; UPDATE public.community_reports SET status=decision WHERE id=report_id; END $$;
REVOKE ALL ON FUNCTION public.resolve_community_report(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.resolve_community_report(uuid,text) TO authenticated;
CREATE FUNCTION public.notify_community_reply() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; parent_author uuid; BEGIN SELECT author_id INTO recipient FROM public.posts WHERE id=NEW.post_id; IF recipient IS NOT NULL AND recipient<>NEW.author_id THEN INSERT INTO public.community_notifications(user_id,kind,target_id,message) VALUES(recipient,'reply',NEW.post_id,'Someone replied to your discussion.'); END IF; IF NEW.parent_id IS NOT NULL THEN SELECT author_id INTO parent_author FROM public.comments WHERE id=NEW.parent_id; IF parent_author IS NOT NULL AND parent_author<>NEW.author_id AND parent_author IS DISTINCT FROM recipient THEN INSERT INTO public.community_notifications(user_id,kind,target_id,message) VALUES(parent_author,'reply',NEW.post_id,'Someone replied to your comment.'); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER community_reply_notification AFTER INSERT ON public.comments FOR EACH ROW EXECUTE FUNCTION public.notify_community_reply();
CREATE FUNCTION public.notify_community_vote() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.community_notifications(user_id,kind,target_id,message) VALUES(NEW.user_id,'vote',NEW.poll_id,'Your community poll vote was saved.'); RETURN NEW; END $$;
CREATE TRIGGER community_vote_notification AFTER INSERT OR UPDATE OF option_index ON public.poll_votes FOR EACH ROW EXECUTE FUNCTION public.notify_community_vote();